#include <bits/stdc++.h>
using namespace std;const int N=105;int a[N],p[N],an[N];int main(int C,char**v){ios::sync_with_stdio(0);cin.tie(0);int R=C>1?stoi(v[1]):1000;unsigned long long s=C>2?stoull(v[2]):1;mt19937_64 g(s);while(R--){int n=g()%100+1;for(int i=1;i<=n;i++)a[i]=g()%1000+1,p[i]=i==1?0:g()%(i-1)+1;for(int i=1;i<=n;i++){int x=p[i];while(x&&__gcd(a[i],a[x])==1)x=p[x];an[i]=x?x:-1;}for(int i=1;i<=n;i++){int x=p[i];while(x&&__gcd(a[i],a[x])==1)x=p[x];if(an[i]!=(x?x:-1))return cout<<"WA\n",1;}int u=g()%n+1;a[u]=g()%1000+1;for(int i=1;i<=n;i++){int x=p[i];while(x&&__gcd(a[i],a[x])==1)x=p[x];an[i]=x?x:-1;}for(int i=1;i<=n;i++){int x=p[i];while(x&&__gcd(a[i],a[x])==1)x=p[x];if(an[i]!=(x?x:-1))return cout<<"WA\n",1;}}cout<<"OK\n";}
